test('shared row and neighbour fibre lead to distinct context lanes', async ({ page }) => {
    await loadTutorial(page);
    await page.locator('[data-step="3"]').click();
    await page.locator('[data-statement="0"]').click();
    const first = await page.evaluate(() => {
        const trace = window.Rdf4jAdjacencyTutorialTesting.getCurrentModel().trace;
        return { row: trace.rowIndex, fiber: trace.fiberIndex, context: trace.contextIndex };
    });
    await expect(page.locator('.tree-row.selected')).toContainText(':alice');
    await expect(page.locator('.tree-fiber.selected')).toContainText(':bob');
    await expect(page.locator('.context-pill.selected')).toContainText(':friends');

    await page.locator('[data-statement="2"]').click();
    const second = await page.evaluate(() => {
        const trace = window.Rdf4jAdjacencyTutorialTesting.getCurrentModel().trace;
        return { row: trace.rowIndex, fiber: trace.fiberIndex, context: trace.contextIndex };
    });
    expect(second.row).toBe(first.row);
    expect(second.fiber).toBe(first.fiber);
    expect(second.context).not.toBe(first.context);
    await expect(page.locator('.context-pill.selected')).toContainText(':work');

    await page.locator('[data-statement="4"]').click();
    await page.locator('[data-step="0"]').click();
    await expect(page.locator('[data-testid="literal-row-note"]')).toBeVisible();
    await expect(page.locator('[data-control="direction"][data-value="incoming"]')).toHaveAttribute('aria-pressed', 'true');
});

test('tail columns show the pair each gap reproduces, not just the gap', async ({ page }) => {
    await loadTutorial(page);
    await page.locator('[data-statement="0"]').click();
    await page.locator('[data-step="5"]').click();

    const neighborTails = page.locator('[data-column="neighborTails"]');
    const contextTails = page.locator('[data-column="contextTails"]');

    // A bare "256" is unreadable; the cell must say which pair the gap bridges.
    await expect(neighborTails).toContainText('+256');
    await expect(neighborTails).toContainText(':bob → :carol');
    await expect(contextTails).toContainText('+256');
    await expect(contextTails).toContainText(':friends → :work');
    await expect(page.getByTestId('tails-note')).toContainText('gaps, not values');

    // Both tail columns are marked as deltas rather than plain values.
    await expect(page.locator('[data-column="neighborTails"] .array-cell.delta')).toHaveCount(1);
    await expect(page.locator('[data-column="contextTails"] .array-cell.delta')).toHaveCount(1);

    // Statement 2 is :alice :knows :carol, the second neighbour of its row, so its neighbour is the one
    // the neighbour tail reconstructs and that cell must be the highlighted one.
    await page.locator('[data-statement="1"]').click();
    await expect(page.locator('[data-column="neighborTails"] .array-cell.selected')).toHaveCount(1);

    // Statement 3 is :alice :knows :bob :work, the second graph of its fibre, so the context tail is highlighted.
    await page.locator('[data-statement="2"]').click();
    await expect(page.locator('[data-column="contextTails"] .array-cell.selected')).toHaveCount(1);

    // Raw-ID mode must still resolve, just in numbers.
    await page.locator('[data-control="terms"][data-value="raw"]').click();
    await expect(neighborTails).toContainText('386 → 642');

    // A page with no second neighbour or graph keeps the omitted explanation instead.
    await page.locator('[data-control="terms"][data-value="labels"]').click();
    await page.locator('[data-statement="7"]').click();
    await expect(neighborTails).toContainText('omitted');
    await expect(contextTails).toContainText('omitted');
    await expect(page.getByTestId('tails-note')).toHaveCount(0);
});

test('re-rendering the same step does not replay the entry animation', async ({ page }) => {
    await loadTutorial(page);
    const frame = page.locator('.lesson-frame');

    // Moving to a different lesson is a real transition, so it animates in.
    await page.locator('[data-step="3"]').click();
    await expect(frame).toHaveClass(/entering/);

    // Everything below re-renders the same lesson. Animating there shifts the content under the
    // pointer by 5px on every click, which reads as the page bumping.
    await page.locator('[data-statement="1"]').click();
    await expect(frame).not.toHaveClass(/entering/);

    await page.locator('[data-control="terms"][data-value="raw"]').click();
    await expect(frame).not.toHaveClass(/entering/);

    await page.locator('[data-control="numbers"][data-value="hex"]').click();
    await expect(frame).not.toHaveClass(/entering/);

    await page.locator('[data-control="direction"][data-value="incoming"]').click();
    await expect(frame).not.toHaveClass(/entering/);

    // Selecting a packed-vector column re-renders in place too.
    await page.locator('[data-control="view"][data-value="vectors"]').click();
    await expect(frame).toHaveClass(/entering/);
    await page.locator('.vector-selector button').last().click();
    await expect(frame).not.toHaveClass(/entering/);

    // Stepping again still animates, so the transition is not simply gone.
    await page.locator('#next-step').click();
    await expect(frame).toHaveClass(/entering/);
});

test('an in-place re-render leaves the heading physically where it was', async ({ page }) => {
    await loadTutorial(page);
    await page.locator('[data-step="3"]').click();
    const heading = page.locator('.lesson-frame h2');
    await expect(heading).toBeVisible();
    // Let the step-change animation finish before measuring the resting position.
    await page.waitForTimeout(400);
    const before = await heading.boundingBox();

    // Toggling term display re-renders the same lesson with the same layout, so nothing should move.
    await page.locator('[data-control="terms"][data-value="raw"]').click();
    const immediately = await heading.boundingBox();
    await page.waitForTimeout(400);
    const settled = await heading.boundingBox();

    // If the entry animation replays, the heading starts 5px low and slides up: immediately !== settled.
    expect(Math.abs(immediately.y - settled.y)).toBeLessThan(0.5);
    expect(Math.abs(settled.y - before.y)).toBeLessThan(0.5);
});

test('keyboard navigation and reduced motion remain usable', async ({ page }) => {
    await page.emulateMedia({ reducedMotion: 'reduce' });
    await loadTutorial(page);
    expect(await page.evaluate(() => matchMedia('(prefers-reduced-motion: reduce)').matches)).toBe(true);

    const statements = page.locator('[data-statement]');
    await statements.nth(0).focus();
    await page.keyboard.press('ArrowDown');
    await expect(statements.nth(1)).toHaveAttribute('aria-selected', 'true');
    await page.keyboard.press('End');
    await expect(statements.nth(7)).toHaveAttribute('aria-selected', 'true');

    await page.locator('[data-step="0"]').focus();
    await page.keyboard.press('ArrowRight');
    await expect(page.locator('[data-step="1"]')).toHaveAttribute('aria-current', 'step');
    await page.keyboard.press('ArrowLeft');
    await expect(page.locator('[data-step="0"]')).toHaveAttribute('aria-current', 'step');

    const animationDuration = await page.locator('.lesson-frame').evaluate((element) => getComputedStyle(element).animationDuration);
    expect(parseFloat(animationDuration)).toBeLessThan(0.01);
});

test('desktop uses side-by-side panels and mobile stacks them', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 900 });
    await loadTutorial(page);
    const desktopStatements = await page.locator('.statement-panel').boundingBox();
    const desktopWorkspace = await page.locator('.workspace').boundingBox();
    expect(desktopStatements.x + desktopStatements.width).toBeLessThan(desktopWorkspace.x);

    await page.setViewportSize({ width: 390, height: 844 });
    await page.reload();
    await expect(page.locator('html')).toHaveAttribute('data-tutorial-ready', 'true');
    const mobileStatements = await page.locator('.statement-panel').boundingBox();
    const mobileWorkspace = await page.locator('.workspace').boundingBox();
    expect(mobileWorkspace.y).toBeGreaterThan(mobileStatements.y + mobileStatements.height);
    await expect(page.locator('[data-statement]')).toHaveCount(8);
    await expect(page.locator('.workspace')).toBeVisible();
});

test('all flags explain both states and the scale diagram traces memory lookup', async ({ page }) => {
    await loadTutorial(page);

    // Every bit in CompactCsfPageFormat gets a button that explains both of its states.
    const PAGE_FLAG_COUNT = 10;
    await page.locator('[data-step="5"]').click();
    const pageFlags = page.locator('[data-page-flag]');
    await expect(pageFlags).toHaveCount(PAGE_FLAG_COUNT);
    for (let index = 0; index < PAGE_FLAG_COUNT; index++) {
        const flag = pageFlags.nth(index);
        const tooltipId = await flag.getAttribute('aria-describedby');
        expect(tooltipId).toBeTruthy();
        await flag.focus();
        const tooltip = page.locator(`#${tooltipId}`);
        await expect(tooltip).toBeVisible();
        await expect(tooltip).toContainText('Set (1):');
        await expect(tooltip).toContainText('Clear (0):');
    }

    await page.locator('[data-control="view"][data-value="physical"]').click();
    const diagram = page.getByTestId('scale-lookup-diagram');
    await expect(diagram).toBeVisible();
    await expect(diagram).toContainText('12 predicates');
    await expect(diagram).toContainText('48 partition slots');
    await expect(diagram).toContainText('2,000 named graphs');
    await expect(diagram.locator('[data-layer]')).toHaveCount(7);

    const vectorFlags = page.locator('[data-vector-flag]');
    await expect(vectorFlags).toHaveCount(2);
    for (let index = 0; index < 2; index++) {
        const flag = vectorFlags.nth(index);
        const tooltipId = await flag.getAttribute('aria-describedby');
        await flag.focus();
        await expect(page.locator(`#${tooltipId}`)).toContainText('Set (1):');
        await expect(page.locator(`#${tooltipId}`)).toContainText('Clear (0):');
    }
});

test('the read lesson rebuilds a row from page bytes and shows what was reconstructed', async ({ page }) => {
    await loadTutorial(page);
    await expect(page.locator('[data-step]')).toHaveCount(10);

    await page.locator('[data-control="view"][data-value="read"]').click();
    await expect(page.locator('[data-tutorial-step="10"]')).toBeVisible();
    await expect(page.getByTestId('read-path')).toBeVisible();

    // Statement 1 is :alice :knows :bob :friends. Its row is :alice, which in partition 0:0 has two
    // distinct neighbours (:bob and :carol) and three quads in total.
    await page.locator('[data-statement="0"]').click();
    const quads = page.getByTestId('read-quads').locator('tbody tr');
    await expect(quads).toHaveCount(3);
    await expect(page.getByTestId('read-quads')).toContainText(':bob');
    await expect(page.getByTestId('read-quads')).toContainText(':carol');
    await expect(page.getByTestId('read-summary')).toContainText('3 quads recovered');
    // Exactly one recovered quad is the selected statement.
    await expect(page.getByTestId('read-quads').locator('tbody tr.current-row')).toHaveCount(1);
    // Partition 0:0 stores every column, so nothing is rebuilt from a flag here.
    await expect(page.locator('.read-step.rebuilt')).toHaveCount(0);
    await expect(page.getByTestId('read-omission-note')).toContainText('happens to store every column');

    // Statement 8 is inferred, landing in the sparse partition 0:2 where the graph is not stored
    // per fibre at all but recovered from the header's commonContext.
    await page.locator('[data-statement="7"]').click();
    await expect(page.locator('#partition-chip')).toContainText('plane 2');
    await expect(page.locator('.read-step.rebuilt').first()).toBeVisible();
    await expect(page.getByTestId('read-quads')).toContainText('commonContext');
    await expect(page.getByTestId('read-summary')).toContainText('1 quad recovered');
    await expect(page.getByTestId('read-omission-note')).toContainText('omissions are safe');

    // Switching direction re-reads the mirrored plane rather than reusing the outgoing answer.
    await page.locator('[data-control="direction"][data-value="incoming"]').click();
    await expect(page.locator('#partition-chip')).toContainText('plane 3');
    await expect(page.getByTestId('read-path')).toBeVisible();
});

test('packed vector and delta deep dives expose exact structure and lifecycle', async ({ page }) => {
    await loadTutorial(page);

    await page.locator('[data-control="view"][data-value="vectors"]').click();
    await expect(page.locator('[data-tutorial-step="7"]')).toBeVisible();
    const vector = page.getByTestId('vector-deep-dive');
    await expect(vector).toBeVisible();
    await expect(vector).toContainText('vector header');
    await expect(vector).toContainText('terminal directory');
    await expect(vector).toContainText('12 B · mode/type · width · count · base');
    await expect(vector.locator('.mode-item')).toHaveCount(4);
    await expect(vector.locator('.mode-item.selected')).toHaveCount(1);
    // A page can only ever write the two FOR forms; the two delta modes must be shown as unreachable.
    await expect(vector.locator('.mode-item.unavailable')).toHaveCount(2);
    await expect(vector.locator('.mode-item.selected.unavailable')).toHaveCount(0);
    await expect(page.getByTestId('mode-reachability')).toContainText('only ever writes the two');
    await page.locator('.vector-selector [data-section="rowIds"]').click();
    await expect(page.getByTestId('vector-deep-dive')).toContainText('rowIds');
    await expect(page.getByTestId('vector-inspector').locator('h3')).toHaveText('rowIds vector');

    // The statement pages are single-block; switching to the 600-row page must show a real multi-block vector.
    await expect(page.getByTestId('vector-span-note')).toContainText('1 block');
    await page.locator('[data-action="vector-source"][data-vector-source="scale"]').click();
    await expect(page.getByTestId('vector-span-note')).toContainText('600 values in 3 blocks');
    await expect(page.getByTestId('vector-span-note')).toContainText('88×');
    await expect(page.locator('.vector-block')).toHaveCount(3);
    // Lane 255 is the last lane of block 0, so the decode route must name block 0 at the boundary.
    await expect(page.getByTestId('vector-deep-dive')).toContainText('255 >>> 8 = block 0');

    await page.locator('[data-control="view"][data-value="deltas"]').click();
    await expect(page.locator('[data-tutorial-step="9"]')).toBeVisible();
    await expect(page.locator('.delta-stage-button')).toHaveCount(5);
    await expect(page.getByTestId('delta-deep-dive')).toContainText('Primitive commit events');

    await page.locator('[data-delta-stage="1"]').click();
    await expect(page.getByTestId('delta-row-merge')).toContainText('New complete row');
    await page.locator('[data-delta-stage="2"]').click();
    await expect(page.getByTestId('delta-generation-directory')).toContainText('runRefs[]');
    await expect(page.locator('.run-byte')).toHaveCount(16);
    await expect(page.getByTestId('delta-deep-dive')).toContainText('SMALL_VARINT');
    await expect(page.getByTestId('delta-deep-dive')).toContainText('BLOCK_FOR');
    await expect(page.getByTestId('delta-deep-dive')).toContainText('CHUNK_DIRECTORY');
    await page.locator('[data-delta-stage="3"]').click();
    await expect(page.getByTestId('delta-read-path')).toContainText('complete run wins');
    await page.locator('[data-delta-stage="4"]').click();
    await expect(page.getByTestId('delta-consolidation')).toContainText('share untouched pages');
});

test('presentation mode fills the screen and keeps one focused artefact per slide', async ({ page }) => {
    await page.setViewportSize({ width: 1800, height: 1100 });
    await loadTutorial(page);
    await expect(page.locator('#present-chrome')).toBeHidden();

    await page.locator('#present-toggle').click();
    await expect(page.locator('html')).toHaveAttribute('data-present', 'true');
    await expect(page.locator('#present-toggle')).toHaveAttribute('aria-pressed', 'true');

    // Every affordance that belongs to the reading layout is gone; only the slide and its own bars remain.
    for (const furniture of ['.masthead', '.statement-panel', '.control-deck', '.step-deck']) {
        await expect(page.locator(furniture)).toBeHidden();
    }
    await expect(page.locator('#present-chrome')).toBeVisible();
    await expect(page.locator('.lesson-frame > h2')).toBeHidden();
    await expect(page.locator('.lesson-frame > .lesson-lead')).toBeHidden();
    await expect(page.locator('.lesson-footer')).toBeHidden();

    // The fibre-tree lesson is deliberately left out of the deck, and entering from it lands on
    // the next lesson that is in the deck rather than jumping backwards.
    const decked = await page.evaluate(() =>
        window.Rdf4jAdjacencyTutorialTesting.presentSlides.map((slide) => slide.step));
    expect(decked).not.toContain(2);
    expect(decked).not.toContain(3);
    expect(decked).toHaveLength(18);
    for (const skipped of ['2', '3']) {
        await page.keyboard.press('Escape');
        await page.locator(`[data-step="${skipped}"]`).click();
        await page.locator('#present-toggle').click();
        await expect(page.locator('.lesson-frame')).toHaveAttribute('data-tutorial-step', '5');
    }
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(0));

    // Slide 1 keeps the concrete statement and the position rules.
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '1');
    await expect(page.locator('#present-counter')).toHaveText('01 / 18');
    await expect(page.locator('#present-title')).not.toBeEmpty();
    await expect(page.locator('.term-strip')).toBeVisible();
    await expect(page.locator('.card-grid')).toBeVisible();

    // The slide is scaled to the screen instead of sitting in a reading column.
    const stage = await page.locator('#present-stage').boundingBox();
    expect(stage.width).toBeGreaterThan(1120);
    expect(stage.width).toBeLessThanOrEqual(1800);
    expect(stage.height).toBeLessThanOrEqual(1100);

    // Arrow keys move between slides in both directions.
    await page.keyboard.press('ArrowRight');
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '2');
    await expect(page.locator('#present-counter')).toHaveText('02 / 18');
    await expect(page.locator('.formula')).toBeVisible();
    await page.keyboard.press('ArrowLeft');
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '1');

    // The packed-vector lesson becomes two slides so the byte line never shares a screen with the ledger.
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(4));
    await expect(page.locator('.vector-byte-line')).toBeVisible();
    await expect(page.locator('.decode-route')).toBeVisible();
    await expect(page.locator('.mode-ledger')).toBeHidden();
    await expect(page.locator('.efficiency-equation')).toBeHidden();
    await page.keyboard.press('ArrowRight');
    await expect(page.locator('.mode-ledger')).toBeVisible();
    await expect(page.locator('.efficiency-equation')).toBeVisible();
    await expect(page.locator('.vector-byte-line')).toBeHidden();

    // The physical lesson splits so the hex dump never shares a screen with the scale map.
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(6));
    await expect(page.locator('.lookup-spine')).toBeVisible();
    await expect(page.getByTestId('physical-bytes')).toBeHidden();
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(11));
    await expect(page.getByTestId('physical-bytes')).toBeVisible();
    await expect(page.locator('.lookup-spine')).toBeHidden();

    // Each delta lifecycle stage is its own slide and drives the underlying stage state.
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(14));
    expect(await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.getState().deltaStage)).toBe(2);
    await expect(page.getByTestId('delta-generation-directory')).toBeVisible();

    // The pipeline doubles as slide navigation, so clicking a stage must move the slide with it.
    await page.locator('[data-delta-stage="4"]').click();
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '17');
    await expect(page.locator('#present-counter')).toHaveText('17 / 18');
    await expect(page.getByTestId('delta-consolidation')).toBeVisible();
    await page.locator('[data-delta-stage="2"]').click();
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '15');

    // Number keys still switch statements without leaving the presentation.
    await page.keyboard.press('3');
    expect(await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.getState().statementIndex)).toBe(2);
    await expect(page.locator('html')).toHaveAttribute('data-present', 'true');

    // Entering the presentation lands on the lesson — and the delta stage — the reader was on.
    await page.keyboard.press('Escape');
    await page.locator('[data-control="view"][data-value="deltas"]').click();
    await page.locator('[data-delta-stage="3"]').click();
    await page.locator('#present-toggle').click();
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '16');
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(14));

    // Escape returns to the reading layout on the lesson the slide was showing.
    await page.keyboard.press('Escape');
    await expect(page.locator('html')).not.toHaveAttribute('data-present', 'true');
    await expect(page.locator('.masthead')).toBeVisible();
    await expect(page.locator('[data-tutorial-step="9"]')).toBeVisible();
    await expect(page.locator('.lesson-footer')).toBeVisible();
    await expect(page.locator('.lesson-frame > h2')).toBeVisible();
});

test('presentation mode stays a live instrument, not a slideshow of screenshots', async ({ page }) => {
    await page.setViewportSize({ width: 1800, height: 1100 });
    await loadTutorial(page);
    await page.locator('#present-toggle').click();
    await expect(page.locator('html')).toHaveAttribute('data-present', 'true');

    // All eight fixture statements stay one click away, and the current one stays marked.
    const chips = page.locator('#present-statements [data-statement]');
    await expect(chips).toHaveCount(8);
    await expect(chips.nth(0)).toHaveAttribute('aria-selected', 'true');
    await chips.nth(5).click();
    await expect(chips.nth(5)).toHaveAttribute('aria-selected', 'true');
    expect(await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.getState().statementIndex)).toBe(5);
    await expect(page.locator('#present-context')).toContainText('_:team');

    // They are a full-height list beside the slide, not a strip squeezed under it, and every
    // statement renders its whole RDF text rather than being cut off mid-term.
    const rail = await page.locator('.present-rail').boundingBox();
    const stage = await page.locator('#present-stage').boundingBox();
    expect(rail.x + rail.width).toBeLessThanOrEqual(stage.x + 1);
    expect(rail.height).toBeGreaterThan(400);
    for (let index = 0; index < 8; index++) {
        const text = chips.nth(index).locator('.statement-rdf');
        const untruncated = await text.evaluate((node) => node.scrollWidth <= node.clientWidth + 1);
        expect(untruncated, `statement ${index + 1} is clipped in the rail`).toBe(true);
    }

    // Only the two controls that change what a slide shows are offered; number base and the
    // lesson picker belong to the reading layout, where there is room to inspect and to browse.
    await expect(page.locator('#present-controls [data-control="direction"]').first()).toBeVisible();
    await expect(page.locator('#present-controls [data-control="terms"]').first()).toBeVisible();
    await expect(page.locator('#present-controls [data-control="numbers"]').first()).toBeHidden();
    await expect(page.locator('#present-controls [data-control="view"]').first()).toBeHidden();

    // Direction and terms still drive the slide that is on screen.
    await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.setPresentSlide(2));
    await expect(page.locator('[data-testid="csr-arrays"]')).toBeVisible();
    await page.locator('#present-controls [data-control="terms"][data-value="raw"]').click();
    await expect(page.locator('[data-array="rowIds"]')).toContainText('130');
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-present-slide', '3');

    await page.locator('#present-controls [data-control="direction"][data-value="incoming"]').click();
    expect(await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.getState().direction)).toBe('incoming');
    await expect(page.locator('#present-context')).toContainText('plane 1');
    await page.locator('#present-controls [data-control="direction"][data-value="outgoing"]').click();
    await expect(page.locator('#present-context')).toContainText('plane 0');

    // The view group is not offered on a slide, but it shares the reading layout's click handler,
    // so that handler must still move the deck rather than only the lesson underneath it.
    await page.locator('#present-controls [data-control="view"][data-value="deltas"]').dispatchEvent('click');
    expect(await page.evaluate(() => window.Rdf4jAdjacencyTutorialTesting.getState().step)).toBe(8);
    await expect(page.locator('.lesson-frame')).toHaveAttribute('data-tutorial-step', '9');
    await expect(page.locator('#present-counter')).toContainText('/ 18');

    // Leaving puts both instruments back where the reading layout expects them.
    await page.locator('#present-exit').click();
    await expect(page.locator('html')).not.toHaveAttribute('data-present', 'true');
    await expect(page.locator('.statement-panel [data-statement]')).toHaveCount(8);
    await expect(page.locator('.control-deck [data-control="direction"]')).toHaveCount(2);
    await page.locator('[data-control="terms"][data-value="labels"]').click();
    await expect(page.locator('[data-statement="5"]')).toHaveAttribute('aria-selected', 'true');
});
